.fh-root .hero{text-align:center;padding:34px 0 8px}
.fh-root .hero h1{font-family:var(--sans);font-size:clamp(30px,5.2vw,50px);font-weight:700;letter-spacing:-.045em;line-height:.98;margin:20px auto 0;max-width:19ch}
.fh-root .hero h1.sec{font-size:clamp(19px,2.6vw,26px);font-weight:600;color:var(--gray);letter-spacing:-.02em;line-height:1.2;margin-top:16px;max-width:24ch}
.fh-root .hero .lede{margin:20px auto 0;font-size:16.5px;color:var(--gray);max-width:50ch}
@media(max-width:640px){.fh-root .hero{padding:22px 0 4px}}
.fh-root .prose{max-width:52ch;margin:34px auto 0;text-align:center}
.fh-root .prose p{margin-top:16px;color:var(--gray);font-size:16.5px;line-height:1.68}
.fh-root .prose p.lead{color:var(--ink);font-size:19px;font-weight:600;letter-spacing:-.02em;margin-top:0}
.fh-root .marq{background:#fff;border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;padding:12px 0}
.fh-root .marq-track{display:flex;width:max-content;animation:fhmarq 34s linear infinite}
.fh-root .marq-set{display:flex;align-items:center}
.fh-root .marq-set span{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--gray);white-space:nowrap;padding:0 16px}
.fh-root .marq-set i{width:10px;height:2px;background:var(--spectrum);border-radius:1px;flex:0 0 auto}
@keyframes fhmarq{to{transform:translateX(-50%)}}
.fh-root footer{background:#FFFFFF;padding:36px 0 0;overflow:hidden;margin-bottom:0}
.fh-root .ghost-mark{width:100%;margin-left:0;margin-top:34px;line-height:0;font-size:0;user-select:none;pointer-events:none;overflow:hidden}
.fh-root .ghost-mark .logo{display:block;width:96vw;aspect-ratio:2698/543;margin:0 auto -4.5vw;opacity:.06;vertical-align:bottom}
.fh-root .disc{max-width:700px;margin:0 auto;font-size:11px;line-height:1.75;color:#5F5F68;text-align:center}
.fh-root .disc p{margin-bottom:12px}
.fh-root .disc strong{color:#2A2A31;font-weight:600}
.fh-root .foot-bottom{margin-top:22px;padding-top:20px;border-top:1px solid var(--line);text-align:center;font-family:var(--mono);font-size:10.5px;letter-spacing:.05em;color:var(--gray)}
.fh-root .foot-bottom a{color:var(--ink2);text-decoration:underline;text-underline-offset:3px}
.fh-root .sysline{margin-top:10px;text-align:center;font-family:var(--mono);font-size:10px;letter-spacing:.12em;color:var(--gray2)}
.fh-root .pulse{width:7px;height:7px;border-radius:50%;background:#A8D8B0;display:inline-block;position:relative;margin-right:8px;vertical-align:middle}
.fh-root .pulse::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:1px solid #A8D8B0;animation:fhpulse 2s ease-out infinite}
@keyframes fhpulse{to{transform:scale(1.9);opacity:0}}

/* what-to-expect steps */
.fh-root .kicker{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--gray2);display:block;text-align:center}
.fh-root .expect{max-width:660px;margin:40px auto 0}
.fh-root .steps{margin-top:20px;border-top:1px solid var(--line)}
.fh-root .step{display:flex;gap:16px;align-items:flex-start;padding:18px 2px;border-bottom:1px solid var(--line);text-align:left}
.fh-root .step .n{font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:.08em;color:var(--gray2);flex:0 0 auto;width:24px;padding-top:4px}
.fh-root .step .t{font-size:16.5px;font-weight:600;letter-spacing:-.015em;color:var(--ink);line-height:1.35}
.fh-root .step .d{margin-top:5px;font-size:15px;color:var(--gray);line-height:1.62}

/* pre-call prep card */
.fh-root .prep{max-width:660px;margin:30px auto 0;background:#fff;border:1px solid var(--line);border-radius:12px;padding:22px 24px;box-shadow:0 1px 3px rgba(10,10,10,.05);text-align:left}
.fh-root .prep .kicker{text-align:left}
.fh-root .prep ul{list-style:none;margin-top:13px}
.fh-root .prep li{position:relative;padding-left:20px;margin-top:10px;font-size:15px;color:var(--gray);line-height:1.6}
.fh-root .prep li::before{content:"";position:absolute;left:0;top:10px;width:10px;height:2px;background:var(--spectrum);border-radius:1px}
.fh-root .signoff{margin:30px auto 0;text-align:center;font-size:16.5px;color:var(--gray)}
@media(max-width:640px){.fh-root .expect{margin-top:30px}.fh-root .prep{padding:20px 18px}}

/* full-bleed white bands: marquee + footer cover the fixed grid edge to edge */
.fh-root .marq,.fh-root footer{width:100vw;margin-left:calc(50% - 50vw);margin-right:calc(50% - 50vw)}


/* FAQ */
.fh-root .faq{max-width:660px;margin:36px auto 0}
.fh-root .faq .steps{margin-top:20px}
.fh-root .faq details{border-bottom:1px solid var(--line)}
.fh-root .faq details:first-of-type{border-top:1px solid var(--line)}
.fh-root .faq summary{cursor:pointer;list-style:none;display:flex;align-items:baseline;gap:14px;padding:16px 2px;font-size:16px;font-weight:600;letter-spacing:-.015em;color:var(--ink);line-height:1.4}
.fh-root .faq summary::-webkit-details-marker{display:none}
.fh-root .faq summary::before{content:"+";font-family:var(--mono);font-size:13px;color:var(--gray2);flex:0 0 auto;width:16px}
.fh-root .faq details[open] summary::before{content:"\2212"}
.fh-root .faq .a{padding:0 2px 18px 30px;font-size:15px;color:var(--gray);line-height:1.66;text-align:left}

/* Add to calendar (shown only when booking handoff exists) */
.fh-root .cal-cta{display:block;max-width:660px;margin:28px auto 0;text-align:center}
.fh-root .cal-cta.is-on{display:block}
.fh-root .cal-cta .kicker{margin-bottom:12px}
.fh-root .cal-cta .cal-when{font-size:15px;color:var(--gray);margin:0 0 16px;line-height:1.5}
.fh-root .cal-cta .cal-actions{display:flex;flex-direction:column;gap:10px;align-items:stretch}
.fh-root .cal-cta .cal-ico{width:18px;height:18px;vertical-align:-4px;margin-right:9px;border-radius:3px}
.fh-root .cal-cta .cal-btn{
  display:block;width:100%;max-width:420px;margin:0 auto;padding:16px 22px;border-radius:9px;
  font-family:var(--sans);font-size:16px;font-weight:600;letter-spacing:-.01em;text-align:center;
  cursor:pointer;text-decoration:none;border:1px solid transparent;box-sizing:border-box;
}
.fh-root .cal-cta .cal-btn-primary{
  background:#188bf6;color:#fff;border-color:#188bf6;
  box-shadow:0 5px 18px rgba(24,139,246,.28);
}
.fh-root .cal-cta .cal-btn-primary:hover{background:#0f7ae5}
.fh-root .cal-cta .cal-btn-secondary{
  background:#fff;color:var(--ink);border-color:var(--line);
}
.fh-root .cal-cta .cal-btn-secondary:hover{background:var(--soft)}

@media(prefers-reduced-motion:reduce){.fh-root .marq-track{animation:none}.fh-root .pulse::after{animation:none;opacity:0}}
